INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (2302, 'math', 2, 'problem_solving', 'ratios_rates', 'advanced', '[See practice test 11 PDF — Math Module 2, Question 27]', NULL, '["157.8", "0", "1", "-1"]', 0, 'The correct answer is 157.8. An area of 46.00 square nautical miles is equivalent to k square kilometers. Since 1 nautical mile equals 1.852 kilometers, 1 square nautical mile equals (1.852)^2 = 3.429904 square kilometers. Multiplying 46.00 by 3.429904 gives approximately 157.8 square kilometers.', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 150, '["student_produced_response", "figure_required"]');